import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_bn_scale_kernel = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_bn_scale_kernel(
    const float* input,
    const float* mean,
    const float* var,
    const float* gamma,
    const float* beta,
    float* output,
    float scaling_factor,
    float eps,
    int num_elements,
    int C, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int c = (idx / (H * W)) % C;

    float inv_std = rsqrtf(var[c] + eps);
    float normalized = (input[idx] - mean[c]) * inv_std;
    output[idx] = (normalized * gamma[c] + beta[c]) * scaling_factor;
}

torch::Tensor fused_bn_scale_cuda(
    torch::Tensor input,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor gamma,
    torch::Tensor beta,
    float scaling_factor,
    float eps) {

    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    const int block_size = 256;
    dim3 grid((num_elements + block_size - 1) / block_size);

    fused_bn_scale_kernel<<<grid, block_size>>>(
        input.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling_factor,
        eps,
        num_elements,
        C, H, W);

    return output;
}
"""

fused_bn_scale_cpp = "torch::Tensor fused_bn_scale_cuda(torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, float, float);"

fused_bn_scale = load_inline(
    name='fused_bn_scale',
    cpp_sources=fused_bn_scale_cpp,
    cuda_sources=fused_bn_scale_kernel,
    functions=['fused_bn_scale_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, padding=kernel_size//2)
        self.scaling_factor = scaling_factor

        # Initialize BN parameters
        self.gamma = nn.Parameter(torch.ones(out_channels))
        self.beta = nn.Parameter(torch.zeros(out_channels))
        self.register_buffer('running_mean', torch.zeros(out_channels))
        self.register_buffer('running_var', torch.ones(out_channels))
        self.eps = 1e-5

    def forward(self, x):
        x = self.conv(x)
        x = fused_bn_scale.fused_bn_scale_cuda(
            x,
            self.running_mean,
            self.running_var,
            self.gamma,
            self.beta,
            self.scaling_factor,
            self.eps
        )
        return x
